async def act(page):
    # Plan (high-level):
    # 1) Use the site-aware search helper to find the requested post by title.
    # 2) Navigate to the post URL (use relative goto when possible).
    # 3) Locate the comment textarea using accessibility-role-centric selectors
    #    (prefer form-scoped textboxes and detect actual <textarea> by tagName).
    # 4) Fill the comment, fill name/email if present, and submit via the form's button.

    # Use the knowledge-base search helper to find the post. This helper navigates to '/'.
    results = await create_curated_collection_by_search(
        page,
        "Why Do I Have No Energy",
        max_results=10,
        resolve_links=True,
    )

    # If no direct matches, try a broader keyword.
    if not results:
        results = await create_curated_collection_by_search(page, "energy", max_results=10, resolve_links=True)

    if not results:
        raise RuntimeError("Could not find the requested post via the site's visible search.")

    # Prefer a title that contains the key phrase; otherwise fall back to the first result.
    target = None
    target_substr = "Why Do I Have No Energy"
    for r in results:
        title = r.get("title", "") if isinstance(r, dict) else ""
        if title and target_substr.lower() in title.lower():
            target = r
            break
    if target is None:
        target = results[0]

    post_url = target.get("url") if isinstance(target, dict) else None
    if not post_url:
        raise RuntimeError(f"Found a result but it has no url: {target}")

    # Navigate to the post page (relative or absolute URL is acceptable here).
    await page.goto(post_url)

    # Wait for main content to appear (best-effort).
    try:
        await page.get_by_role("main").wait_for(state="visible", timeout=5000)
    except Exception:
        # continue even if wait fails
        pass

    # Strategy to find the comment textarea:
    #  - Prefer a <textarea> element inside a role="form" (accessed as role="textbox" in ARIA).
    #  - Fall back to any page-level textbox that is a textarea element.

    comment_locator = None
    comment_form = None

    forms = page.get_by_role("form")
    try:
        forms_count = await forms.count()
    except Exception:
        forms_count = 0

    for i in range(forms_count):
        form = forms.nth(i)
        # Look for textboxes inside this form
        textboxes = form.get_by_role("textbox")
        try:
            tb_count = await textboxes.count()
        except Exception:
            tb_count = 0
        for j in range(tb_count):
            tb = textboxes.nth(j)
            try:
                tag = await tb.evaluate("el => el.tagName.toLowerCase()")
            except Exception:
                tag = ""
            if tag == "textarea":
                comment_locator = tb
                comment_form = form
                break
        if comment_locator:
            break

    # If not found inside forms, check every textbox on the page for a textarea tagName.
    if comment_locator is None:
        all_textboxes = page.get_by_role("textbox")
        try:
            all_count = await all_textboxes.count()
        except Exception:
            all_count = 0
        for k in range(all_count):
            tb = all_textboxes.nth(k)
            try:
                tag = await tb.evaluate("el => el.tagName.toLowerCase()")
            except Exception:
                tag = ""
            if tag == "textarea":
                comment_locator = tb
                # try to find its containing form (walk up via evaluate)
                try:
                    has_form = await tb.evaluate("el => !!(el.form)")
                    if has_form:
                        # attempt to find the closest ancestor form and wrap it as a locator
                        # We can't construct a role-scoped locator for an arbitrary ancestor easily,
                        # so leave comment_form as None (we'll still try to submit using page-scoped button heuristics).
                        comment_form = None
                except Exception:
                    comment_form = None
                break

    if comment_locator is None:
        raise RuntimeError("Could not locate a comment textarea on the post page.")

    # Fill the comment text
    await comment_locator.fill("Thank you for this helpful guide.")

    # If we discovered a form containing the comment, attempt to fill name/email inside that form.
    if comment_form is not None:
        # Look for single-line textboxes inside the form (often used for name and email).
        inputs = comment_form.get_by_role("textbox")
        try:
            inputs_count = await inputs.count()
        except Exception:
            inputs_count = 0

        # heuristics: find inputs whose name/id includes 'author' or 'name' for author,
        # and 'email' for email.
        author_filled = False
        email_filled = False
        for m in range(inputs_count):
            inp = inputs.nth(m)
            # Skip the textarea we already filled (it is a textbox too), detect by tagName.
            try:
                tag = await inp.evaluate("el => el.tagName.toLowerCase()")
            except Exception:
                tag = ""
            if tag == "textarea":
                continue
            # read attributes to decide what this input likely is
            try:
                attr_name = (await inp.get_attribute("name")) or ""
            except Exception:
                attr_name = ""
            try:
                attr_id = (await inp.get_attribute("id")) or ""
            except Exception:
                attr_id = ""
            try:
                aria = (await inp.get_attribute("aria-label")) or ""
            except Exception:
                aria = ""
            try:
                placeholder = (await inp.get_attribute("placeholder")) or ""
            except Exception:
                placeholder = ""

            combined = f"{attr_name} {attr_id} {aria} {placeholder}".lower()
            if ("author" in combined) or ("name" in combined and not author_filled):
                try:
                    await inp.fill("Playwright Test")
                    author_filled = True
                except Exception:
                    pass
                continue
            if "email" in combined and not email_filled:
                try:
                    await inp.fill("playwright@example.com")
                    email_filled = True
                except Exception:
                    pass
                continue
        # end for

    else:
        # No form found: try to fill name/email via page-scoped textboxes that look like author/email
        all_textboxes = page.get_by_role("textbox")
        try:
            all_count = await all_textboxes.count()
        except Exception:
            all_count = 0
        author_filled = False
        email_filled = False
        for n in range(all_count):
            tb = all_textboxes.nth(n)
            try:
                tag = await tb.evaluate("el => el.tagName.toLowerCase()")
            except Exception:
                tag = ""
            # skip the textarea already used
            if tag == "textarea":
                continue
            try:
                name_attr = (await tb.get_attribute("name")) or ""
            except Exception:
                name_attr = ""
            try:
                id_attr = (await tb.get_attribute("id")) or ""
            except Exception:
                id_attr = ""
            try:
                aria = (await tb.get_attribute("aria-label")) or ""
            except Exception:
                aria = ""
            try:
                placeholder = (await tb.get_attribute("placeholder")) or ""
            except Exception:
                placeholder = ""
            combined = f"{name_attr} {id_attr} {aria} {placeholder}".lower()
            if ("author" in combined or "name" in combined) and not author_filled:
                try:
                    await tb.fill("Playwright Test")
                    author_filled = True
                except Exception:
                    pass
            if "email" in combined and not email_filled:
                try:
                    await tb.fill("playwright@example.com")
                    email_filled = True
                except Exception:
                    pass
            if author_filled and email_filled:
                break

    # Finally, submit the comment:
    # Prefer a button inside the discovered form; if none try page-scoped buttons with likely names.
    submit_clicked = False
    if comment_form is not None:
        # Try a few likely button names within the form
        for btn_name in ["Post Comment", "Post Comment", "Submit", "Submit Comment", "Send"]:
            try:
                btns = comment_form.get_by_role("button", name=btn_name)
                if await btns.count() > 0:
                    await btns.first.click()
                    submit_clicked = True
                    break
            except Exception:
                continue
        # If no named button, click the first button in the form
        if not submit_clicked:
            try:
                btns_any = comment_form.get_by_role("button")
                if await btns_any.count() > 0:
                    await btns_any.first.click()
                    submit_clicked = True
            except Exception:
                pass

    if not submit_clicked:
        # Try page-level buttons with likely names (accessibility-role-centric)
        for btn_name in ["Post Comment", "Submit", "Send"]:
            try:
                btns = page.get_by_role("button", name=btn_name)
                if await btns.count() > 0:
                    await btns.first.click()
                    submit_clicked = True
                    break
            except Exception:
                continue

    if not submit_clicked:
        # As a last resort, attempt to submit the form element that contains the textarea via evaluate()
        try:
            await comment_locator.evaluate("el => { const f = el.form || document.querySelector('form'); if(f) { f.submit(); return true; } return false; }")
            # We won't rely on the boolean here; assume submission attempted.
        except Exception:
            raise RuntimeError("Could not submit the comment form or find an appropriate submit control.")

    # End of actions. Do not return any extra data.
    return

